package com.aac.ieojwo.report.service;
import com.aac.ieojwo.alert.domain.AlertType;import com.aac.ieojwo.alert.service.AlertService;import com.aac.ieojwo.common.exception.BadRequestException;import com.aac.ieojwo.device.domain.AacDevice;import com.aac.ieojwo.live.LiveEventService;import com.aac.ieojwo.report.domain.*;import com.aac.ieojwo.report.repository.SensorEventRepository;import com.aac.ieojwo.user.domain.UserStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.Map;
@Service public class SensorService{public record SensorRequest(SensorEventType type,Double numericValue,String label,Instant recordedAt){}public record SensorResponse(Long id,SensorEventType type,Double numericValue,String label,Instant recordedAt){public static SensorResponse from(SensorEvent e){return new SensorResponse(e.getId(),e.getEventType(),e.getNumericValue(),e.getLabel(),e.getRecordedAt());}}private final SensorEventRepository repo;private final AlertService alerts;private final LiveEventService live;public SensorService(SensorEventRepository r,AlertService a,LiveEventService l){repo=r;alerts=a;live=l;}@Transactional public SensorResponse record(AacDevice d,SensorRequest r){if(r.type()==null)throw new BadRequestException("센서 유형이 필요합니다.");if(r.type()==SensorEventType.HEART_RATE&&(r.numericValue()==null||r.numericValue()<20||r.numericValue()>250))throw new BadRequestException("심박수 범위가 올바르지 않습니다.");SensorEvent e=repo.save(SensorEvent.create(d,r.type(),r.numericValue(),r.label(),r.recordedAt()));if(r.type()==SensorEventType.HEART_RATE&&r.numericValue()>=110)alerts.create(d.getUser(),AlertType.HEART_RATE,"고심박 감지","심박수 "+r.numericValue().intValue()+" BPM이 감지되었습니다.");live.publish(d.getUser().getId(),"SENSOR_EVENT",SensorResponse.from(e));return SensorResponse.from(e);}@Transactional public void emergency(AacDevice d,String message){d.getUser().updateStatus(UserStatus.EMERGENCY);alerts.create(d.getUser(),AlertType.EMERGENCY,"긴급 모드",message==null||message.isBlank()?"사용자 기기에서 긴급 모드가 실행되었습니다.":message);live.publish(d.getUser().getId(),"STATUS_UPDATED",Map.of("status","EMERGENCY"));}}
